package d2s

import (
	"text/template"
	"time"
)

var tpl = template.Must(
	template.New("").
		Parse(`// НЕ РЕДАКТИРОВАТЬ! Изменения будут перезаписаны при следующей генерации.
// Code generated by running "go generate" by utility db2struct: "https://github.com/webnice/d2s"; DO NOT EDIT.
// Generator: db2struct (go install github.com/webnice/d2s/db2struct@latest)

// Структура создана автоматически на основе структуры таблицы базы данных.
// Название таблицы: "{{ .Table }}"

package {{ .Package }}

{{ if .Imports }}{{ .Imports }}
{{ end -}}
{{- $cf := .ColumnsFormat }}
// {{ .Struct }} {{ .Comment }}
type {{ .Struct }} struct {
{{- range .Columns }}
	{{ printf $cf .Name .Type .Tags .Comment }}
{{- end }}
}
`))

type tplVar struct {
	Timestamp        time.Time
	Database         string
	Table            string
	Package          string
	Struct           string
	Comment          string
	Columns          []*tplVarCol
	ColumnsFormat    string
	ColumnNameLength int
	ColumnTypeLength int
	ColumnTagsLength int
	Imports          string
}

type tplVarCol struct {
	Name    string
	Type    string
	Tags    string
	Comment string
}
